struct Config {
  input : String
  stdin : Bool
}

///|
async fn main {
  let config = @argparse.parse(
    Command(
      "tomljson",
      about="Convert TOML to JSON. Reads from file or stdin.",
      flags=[
        FlagArg(
          "stdin",
          long="stdin",
          about="Read TOML from stdin instead of a file.",
        ),
      ],
      positionals=[
        PositionArg(
          "input",
          default_values=["-"],
          about="Input TOML file path.",
        ),
      ],
    ),
  ) |> config_from_matches

  let toml_text = if config.stdin {
    @stdio.stdin.read_all().text()
  } else {
    @fs.read_file(config.input).text()
  }

  match @toml.parse(toml_text) {
    json => {
      println(json.stringify())
    }
  } catch {
    ParseError::DuplicateKey(msg, _) => {
      @stdio.stderr.write_string("error: \{msg}\n")
    }
    ParseError::InvalidTable(msg) => {
      @stdio.stderr.write_string("error: \{msg}\n")
    }
    ParseError::InvalidValue(msg) => {
      @stdio.stderr.write_string("error: \{msg}\n")
    }
    ParseError::InvalidString(msg) => {
      @stdio.stderr.write_string("error: \{msg}\n")
    }
    ParseError::DottedKeyConflict(msg) => {
      @stdio.stderr.write_string("error: \{msg}\n")
    }
  }
}

///|
fn config_from_matches(matches : @argparse.Matches) -> Config raise {
  match matches {
    {
      values: { "input"? : Some([input, ..]), .. },
      flags: { "stdin"? : Some(stdin), .. },
      ..,
    } => { input, stdin }
    {
      values: { "input"? : Some([input, ..]), .. },
      flags: { "stdin"? : None, .. },
      ..,
    } => {
      let stdin = false
      { input, stdin }
    }
    _ => fail("missing parsed argument: input")
  }
}
