///|
/// TOML parser library. Parses a subset of TOML into JSON.
/// Supports:
/// - comments (#)
/// - blank lines and whitespace
/// - bare keys and dotted keys
/// - tables [owner] and nested tables [database.settings]
/// - strings with \", \\, \n, \t escapes
/// - integers, booleans
/// - arrays of integers, booleans, strings
/// - duplicate-key errors

///|
/// Error type for TOML parsing failures.
suberror ParseError {
  DuplicateKey(String)
  InvalidTable(String)
  InvalidValue(String)
  InvalidString(String)
  DottedKeyConflict(String)
} derive(Debug)

///|
/// Parse TOML text into a Json value.
pub fn parse(input : String) -> Json raise ParseError {
  let root = Json::object(Map([]))
  let current_path : Array[String] = []

  for line_v in input.split("\n") {
    let line = line_v.to_owned()
    let trimmed = line.trim().to_owned()

    // Skip blank lines and comments
    if trimmed.is_empty() || trimmed.has_prefix("#") {
      continue
    }

    if trimmed.has_prefix("[") {
      let table_name = parse_table_header(trimmed)
      // Build the current path
      current_path.clear()
      for part in table_name.split(".") {
        let p = part.trim().to_owned()
        if p.is_empty() {
          raise ParseError::InvalidTable(
            "empty segment in table name: \{table_name}",
          )
        }
        current_path.push(p)
      }
    } else if trimmed.contains("=") {
      parse_key_value(trimmed, root, current_path)
    } else {
      raise ParseError::InvalidValue("unexpected line: \{trimmed}")
    }
  }

  root
}

///|
fn parse_table_header(line : String) -> String raise ParseError {
  if !line.has_prefix("[") || !line.has_suffix("]") {
    raise ParseError::InvalidTable("invalid table header: \{line}")
  }
  let name = line.sub(start=1, end=line.length() - 1).to_owned().trim().to_owned()
  if name.is_empty() {
    raise ParseError::InvalidTable("empty table name: \{line}")
  }
  name
}

///|
fn parse_key_value(
  line : String,
  root : Json,
  current_path : Array[String]
) -> Unit raise ParseError {
  let eq_pos = line.find("=")
  match eq_pos {
    Some(pos) => {
      let key_part = line.sub(start=0, end=pos).to_owned().trim().to_owned()
      let value_part = line.sub(start=pos + 1).to_owned().trim().to_owned()

      // Parse the value
      let value = parse_value(value_part)

      // Split key on dots
      let keys : Array[String] = []
      for k in key_part.split(".") {
        keys.push(k.trim().to_owned())
      }

      // Navigate to the current table, creating nested objects as needed
      let mut parent = root
      for table_name in current_path {
        match parent {
          Json::Object(map) => {
            if map.contains(table_name) {
              match map[table_name] {
                Json::Object(_) => {
                  parent = map[table_name]
                }
                _ =>
                  raise ParseError::DottedKeyConflict(
                    "table '\{table_name}' is not an object",
                  )
              }
            } else {
              let new_obj = Json::object(Map([]))
              map.set(table_name, new_obj)
              parent = new_obj
            }
          }
          _ => raise ParseError::InvalidTable("parent is not an object")
        }
      }

      // Set the key(s) in the current table
      set_nested_key(parent, keys, value)
    }
    None => raise ParseError::InvalidValue("missing '=' in: \{line}")
  }
}

///|
fn set_nested_key(
  parent : Json,
  keys : Array[String],
  value : Json
) -> Unit raise ParseError {
  match parent {
    Json::Object(map) => {
      if keys.length() == 1 {
        let key = keys[0]
        if map.contains(key) {
          raise ParseError::DuplicateKey("duplicate key '\{key}'")
        }
        map.set(key, value)
      } else {
        let first = keys[0]
        let rest = sub_array(keys, 1)
        if !map.contains(first) {
          map.set(first, Json::object(Map([])))
        }
        match map[first] {
          Json::Object(_) => {
            set_nested_key(map[first], rest, value)
          }
          _ =>
            raise ParseError::DottedKeyConflict(
              "key '\{first}' is not an object, cannot set '\{keys.join(".")}'",
            )
        }
      }
    }
    _ => raise ParseError::InvalidValue("cannot set key on non-object")
  }
}

///|
fn sub_array[T](arr : Array[T], start : Int) -> Array[T] {
  let result : Array[T] = []
  for i = start; i < arr.length(); i = i + 1 {
    result.push(arr[i])
  }
  result
}

///|
fn parse_value(text : String) -> Json raise ParseError {
  let s = text.trim().to_owned()
  if s == "" {
    raise ParseError::InvalidValue("empty value")
  }
  if s.has_prefix("\"") {
    parse_string(s)
  } else if s == "true" {
    Json::boolean(true)
  } else if s == "false" {
    Json::boolean(false)
  } else if s == "[]" {
    Json::array([])
  } else if s.has_prefix("[") && s.has_suffix("]") {
    parse_array(s)
  } else {
    parse_integer(s)
  }
}

///|
fn parse_string(text : String) -> Json raise ParseError {
  if text.length() < 2 || !text.has_prefix("\"") || !text.has_suffix("\"") {
    raise ParseError::InvalidString("invalid string: \{text}")
  }
  let inner = text.sub(start=1, end=text.length() - 1).to_owned()
  let buf = StringBuilder::new()
  let mut i = 0
  while i < inner.length() {
    let ch = inner[i]
    if ch == '\\' {
      if i + 1 >= inner.length() {
        raise ParseError::InvalidString("trailing backslash")
      }
      let next = inner[i + 1]
      match next {
        '"' => {
          buf.write_char('"')
          i = i + 2
          continue
        }
        '\\' => {
          buf.write_char('\\')
          i = i + 2
          continue
        }
        'n' => {
          buf.write_char('\n')
          i = i + 2
          continue
        }
        't' => {
          buf.write_char('\t')
          i = i + 2
          continue
        }
        _ =>
          raise ParseError::InvalidString(
            "unknown escape \\\\\{next.to_string()}",
          )
      }
    } else {
      buf.write_char(ch)
      i = i + 1
    }
  }
  Json::string(buf.to_string())
}

///|
fn parse_integer(text : String) -> Json raise ParseError {
  let s = text.trim().to_owned()
  let negative = s.has_prefix("-")
  let digits = if negative { s.sub(start=1).to_owned() } else { s }
  if digits.is_empty() {
    raise ParseError::InvalidValue("empty integer: \{text}")
  }
  for ch in digits {
    if ch.to_int() < '0'.to_int() || ch.to_int() > '9'.to_int() {
      raise ParseError::InvalidValue("invalid integer: \{text}")
    }
  }
  let n : Int = @string.from_str(s) catch {
    _ => raise ParseError::InvalidValue("invalid integer: \{text}")
  }
  // Preserve integer representation
  Json::number(n.to_double(), repr=s)
}

///|
fn parse_array(text : String) -> Json raise ParseError {
  let inner = text.sub(start=1, end=text.length() - 1).to_owned().trim().to_owned()
  if inner.is_empty() {
    return Json::array([])
  }
  let arr : Array[Json] = []
  for part in inner.split(",") {
    let v = part.trim().to_owned()
    if !v.is_empty() {
      arr.push(parse_value(v))
    }
  }
  Json::array(arr)
}

